/* Native section surface and typography */
&.fdp-j-private-parties{padding:clamp(28px,5vw,76px) clamp(18px,5vw,72px);background:#f3eee5;color:#241c19;font-family:Arial,sans-serif;} &.fdp-j-private-parties h2{color:#241c19;line-height:1.06;letter-spacing:-.025em;font-size:clamp(32px,4.4vw,62px);} &.fdp-j-private-parties h3{color:#241c19;font-family:Arial,sans-serif;font-size:clamp(21px,2.1vw,30px);line-height:1.15;margin:0 0 14px;} &.fdp-j-private-parties p{color:#241c19;line-height:1.7;} &.fdp-j-private-parties .fdp-content{max-width:1160px;margin:24px auto 0;} &.fdp-j-private-parties .fdp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;} &.fdp-j-private-parties .fdp-card{padding:clamp(22px,3vw,40px);background:#fffaf2;border:1px solid #a89e91;} &.fdp-j-private-parties .fdp-card p{margin-bottom:0;} &.fdp-j-private-parties .fdp-kicker{font-family:Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;margin:0 0 18px;} &.fdp-j-private-parties .fdp-action{display:inline-flex;align-items:center;justify-content:center;gap:12px;min-height:48px;padding:14px 24px;background:#a94728;color:#fffaf1;font:700 13px/1.3 Arial,sans-serif;letter-spacing:.06em;text-decoration:none;} &.fdp-j-private-parties .fdp-action:focus-visible{outline:3px solid #241c19;outline-offset:4px;} &.fdp-j-private-parties .fdp-action:hover{text-decoration:underline;} &.fdp-j-private-parties .fdp-actions{margin:28px 0 0;} &.fdp-j-private-parties .fdp-number{display:block;color:#a94728;font:700 13px/1.2 Arial,sans-serif;letter-spacing:.15em;margin-bottom:20px;} &.fdp-j-private-parties .fdp-list{margin:0;padding:0;list-style:none;} &.fdp-j-private-parties .fdp-list li{padding:16px 0;border-bottom:1px solid #a89e91;line-height:1.6;} @media(max-width:720px){&.fdp-j-private-parties .fdp-grid{grid-template-columns:1fr;} &.fdp-j-private-parties .fdp-card{padding:24px;} &.fdp-j-private-parties .fdp-action{width:100%;box-sizing:border-box;}} &.fdp-j-private-parties h2{font-weight:900;}&.fdp-j-private-parties .fdp-hire-desk{display:grid;grid-template-columns:1.4fr 1fr;gap:30px;}&.fdp-j-private-parties .fdp-desk-row{display:grid;grid-template-columns:40px 1fr;gap:16px;padding:22px 0;border-top:1px solid #a89e91;}&.fdp-j-private-parties .fdp-desk-row .fdp-number{padding-top:4px;}&.fdp-j-private-parties .fdp-desk-row p{margin:0;}&.fdp-j-private-parties .fdp-next{background:#fffaf2;border:2px solid #241c19;padding:32px;align-self:start;}&.fdp-j-private-parties .fdp-next .fdp-list li{font-weight:700;}@media(max-width:720px){&.fdp-j-private-parties .fdp-hire-desk{grid-template-columns:1fr;}}
/* Keep content within the section on narrow screens */
&.fdp-j-private-parties,&.fdp-j-private-parties *{box-sizing:border-box;}&.fdp-j-private-parties .fdp-content,&.fdp-j-private-parties .fdp-content>*,&.fdp-j-private-parties .fdp-content article,&.fdp-j-private-parties .fdp-content aside{min-width:0;}&.fdp-j-private-parties p,&.fdp-j-private-parties li,&.fdp-j-private-parties a{overflow-wrap:break-word;}
&.fdp-j-private-parties{background:#f3eee5!important;} &.fdp-j-private-parties h2{color:#241c19!important;}
